#include <stdio.h>
int main(void){
    int n=4;
    int deg[4]={0,1,1,2};
    int adj[4][4]={0};
    adj[0][1]=adj[0][2]=adj[1][3]=adj[2][3]=1;  /* 0→1, 0→2, 1→3, 2→3 */
    int q[4], head=0, tail=0;
    for (int i=0;i<n;i++) if (deg[i]==0) q[tail++]=i;
    printf("topological order: ");
    while (head<tail){
        int u=q[head++]; printf("%d ", u);
        for (int v=0;v<n;v++) if (adj[u][v] && --deg[v]==0) q[tail++]=v;
    }
    printf("\n");
    return 0;
}
